/**
 * Node: STATS (Optimized with Lazy Caching)
 * Eliminates background bloat. Calculates Top Systems, Alliance Activity, and Trends on-demand.
 */
const Redis = require('ioredis');

const inputData = $input ? $input.first().json : items[0].json;
const params = inputData.query || {};

const REDIS_CONFIG = { 
    host: 'redis', 
    port: 6379, 
    db: 0, 
    connectTimeout: 5000, 
    maxRetriesPerRequest: 2 
};
const STATS_WINDOW_DAYS = 30;
const CACHE_TTL = 300; // Cache stats for 5 minutes

const KEY_KILLS_ALL = 'intel:kills:all';
const KEY_STATS_24H = 'intel:kills:24h_stats';
const KEY_KILL_DATA = 'intel:kill:data';
const KEY_CACHED_STATS = 'intel:cached:stats';
const KEY_CACHED_TRENDS = 'intel:cached:trends';

const allianceIdParam = params.alliance_id ? String(params.alliance_id) : null;
const allianceIds = new Set(allianceIdParam ? allianceIdParam.split(',').map(s => s.trim()).filter(Boolean) : []);
const corpIdParam = params.corporation_id ? String(params.corporation_id) : null;
const corpIds = new Set(corpIdParam ? corpIdParam.split(',').map(s => s.trim()).filter(Boolean) : []);

const redis = new Redis(REDIS_CONFIG);

async function calculateGlobalStats() {
    console.log("[STATS] Cache miss/stale. Recalculating global stats...");
    const now = Math.floor(Date.now() / 1000);
    const thirtyDaysAgo = now - (86400 * 30);
    const twentyFourHoursAgo = now - 86400;
    const fortyEightHoursAgo = now - (86400 * 2);
    const sixtyDaysAgo = now - (86400 * 60);

    const pipe = redis.pipeline();

    // 1. Fetch Ranges
    pipe.zcount(KEY_KILLS_ALL, thirtyDaysAgo, now);
    pipe.zcount(KEY_KILLS_ALL, sixtyDaysAgo, now);
    pipe.zrangebyscore(KEY_STATS_24H, twentyFourHoursAgo, now, 'WITHSCORES');
    pipe.zrangebyscore(KEY_STATS_24H, fortyEightHoursAgo, twentyFourHoursAgo, 'WITHSCORES');
    pipe.zrevrange(KEY_KILLS_ALL, 0, 0, 'WITHSCORES'); // Newest Kill ID

    // 2. Hourly Heatmap Buckets
    for(let h=0; h<24; h++) pipe.zcount(`intel:kills:hour:${h}`, thirtyDaysAgo, now);

    // 3. Daily History
    for (let i = 29; i >= 0; i--) {
        const start = now - ((i + 1) * 86400);
        const end = now - (i * 86400);
        pipe.zcount(KEY_KILLS_ALL, start, end);
    }

    const results = await pipe.exec();

    // Parse Basic Counts
    const total_count = results[0][1] || 0;
    const total_count_60d = results[1][1] || 0;
    const kills24hRaw = results[2][1] || [];
    const killsPrev24hRaw = results[3][1] || [];
    const newestKillId = results[4][1]?.[0] || null;

    // --- HEAVY LIFTING: Process 24h Kills (ISK, Top Systems, Last Seen) ---
    let isk24h = 0;
    let top_systems = [];
    let allianceUpdates = {}; // Map of allianceId -> lastSeen timestamp

    if (kills24hRaw.length > 0) {
        // Fetch full kill data for 24h period
        const p = redis.pipeline();
        for(let i=0; i<kills24hRaw.length; i+=2) p.hget(KEY_KILL_DATA, kills24hRaw[i]);
        const res = await p.exec();

        const systemCounts = {};

        res.forEach(([err, json]) => {
            if(!err && json) {
                const k = JSON.parse(json);
                // 1. ISK Sum
                isk24h += (Number(k.total_value) || 0);

                // 2. System Counts
                const sys = k.solar_system_name || 'Unknown';
                systemCounts[sys] = (systemCounts[sys] || 0) + 1;

                // 3. Track Alliance Last Seen
                const killTime = new Date(k.killmail_time).getTime() / 1000;
                const check = (id) => {
                    if(id) { 
                        const sid = String(id);
                        if(!allianceUpdates[sid] || killTime > allianceUpdates[sid]) allianceUpdates[sid] = killTime;
                    }
                };
                if (k.victim?.alliance_id) check(k.victim.alliance_id);
                if (k.attackers) k.attackers.forEach(a => check(a.alliance_id));
            }
        });

        // Sort Top Systems
        top_systems = Object.entries(systemCounts)
            .sort((a, b) => b[1] - a[1])
            .slice(0, 10)
            .map(([name, count]) => ({ name, count }));
    }

    // Process Prev 24h ISK (needed for trends)
    let iskPrev24h = 0;
    if (killsPrev24hRaw.length > 0) {
        const p = redis.pipeline();
        for(let i=0; i<killsPrev24hRaw.length; i+=2) p.hget(KEY_KILL_DATA, killsPrev24hRaw[i]);
        const res = await p.exec();
        res.forEach(([err, json]) => { if(!err && json) iskPrev24h += (Number(JSON.parse(json).total_value)||0); });
    }

    const kills_24h = kills24hRaw.length / 2;
    const kills_prev_24h = killsPrev24hRaw.length / 2;

    // Trends Logic
    const getTrend = (curr, prev) => {
        if (prev === 0) return 'stable';
        const chg = ((curr - prev) / prev) * 100;
        return chg >= 50 ? 'heating' : (chg >= 10 ? 'rising' : (chg <= -50 ? 'cooling' : (chg <= -10 ? 'falling' : 'stable')));
    };

    const stats_24h = { kills: kills_24h, isk: isk24h };
    const trends = {
        kills: getTrend(kills_24h, kills_prev_24h),
        isk: getTrend(isk24h, iskPrev24h),
        total30d: getTrend(total_count, total_count_60d - total_count)
    };

    // Heatmap Logic
    const activity_heatmap = {};
    const bucket = (list) => {
        const b = new Array(24).fill(0);
        for(let i=0; i<list.length; i+=2) b[new Date(parseFloat(list[i+1])*1000).getUTCHours()]++;
        return b;
    };
    const todayB = bucket(kills24hRaw);
    const yestB = bucket(killsPrev24hRaw);
    for(let h=0; h<24; h++) {
        activity_heatmap[h] = { avg: Math.round((results[5+h][1]||0)/30), today: todayB[h], yesterday: yestB[h] };
    }

    // Daily Stats Logic
    const daily_stats = [];
    for(let i=0; i<30; i++) {
        const d = new Date(now * 1000 - ((29-i)*86400000));
        daily_stats.push({ label: `${d.getUTCDate()}/${d.getUTCMonth()+1}`, count: results[29+i][1]||0 });
    }

    // Update Cache
    const cacheObj = {
        stats_24h, total_count, activity_heatmap, daily_stats, top_systems,
        latest_db_killmail_time: newestKillId ? new Date().toISOString() : null
    };

    const writePipe = redis.pipeline()
        .set(KEY_CACHED_STATS, JSON.stringify(cacheObj), 'EX', CACHE_TTL)
        .set(KEY_CACHED_TRENDS, JSON.stringify(trends), 'EX', CACHE_TTL);

    // Apply Alliance 'Last Seen' Updates (Lazy Write)
    Object.entries(allianceUpdates).forEach(([id, ts]) => {
        writePipe.hset(`alliance:summary:${id}`, 'lastSeen', ts);
    });

    await writePipe.exec();

    return { stats: cacheObj, trends };
}

return (async () => {
    try {
        // 1. Try Fetching Cached Global Stats
        let [csRes, ctRes] = await redis.pipeline().get(KEY_CACHED_STATS).get(KEY_CACHED_TRENDS).exec();

        let statsData, trendsData;

        if (csRes[1] && ctRes[1]) {
            statsData = JSON.parse(csRes[1]);
            trendsData = JSON.parse(ctRes[1]);
        } else {
            // LAZY LOADING: Cache missing/stale, compute now
            const computed = await calculateGlobalStats();
            statsData = computed.stats;
            trendsData = computed.trends;
        }

        // 2. Fetch ISK Distribution (Cheap ZCOUNTs)
        const pipe = redis.pipeline();
        const win = Math.floor(Date.now()/1000) - (STATS_WINDOW_DAYS * 86400);
        ['sub10m','10m-100m','100m-1b','1b-10b','10b-20b','20b-50b','50b'].forEach(f => pipe.zcount(`intel:kills:isk:${f}`, win, '+inf'));

        // 3. Fetch Specific Alliance Stats (if requested)
        const idsList = Array.from(allianceIds);
        idsList.forEach(id => pipe.hgetall(`alliance:summary:${id}`));
        const corpIdsList = Array.from(corpIds);
        corpIdsList.forEach(id => pipe.hgetall(`corporation:summary:${id}`));

        // 4. Matrix (Only if few alliances to prevent explosion)
        let matrixPairs = [];
        if (idsList.length >= 2 && idsList.length <= 10) {
             for(let i=0; i<idsList.length; i++) 
                for(let j=0; j<idsList.length; j++) 
                    if(i!==j) { 
                        matrixPairs.push({k:idsList[i],v:idsList[j]}); 
                        pipe.zcount(`intel:interaction:${idsList[i]}:${idsList[j]}`, win, '+inf'); 
                    }
        }

        const res = await pipe.exec();

        // Process ISK Dist
        let isk_distribution = {};
        const t30 = statsData.total_count || 1;
        ['sub10m','10m-100m','100m-1b','1b-10b','10b-20b','20b-50b','50b'].forEach((k,i) => {
            isk_distribution[k] = { count: res[i][1], percent: parseFloat(((res[i][1]/t30)*100).toFixed(1)) };
        });

        // Process Alliance Stats
        let allianceStatsDict = {};
        let allianceSummary = null;
        let corpStatsDict = {};
        let offset = 7; // 7 ISK buckets

        if (idsList.length > 0) {
            idsList.forEach((id, i) => {
                const s = res[offset + i][1];
                if (s && Object.keys(s).length > 0) {
                    allianceStatsDict[id] = { 
                        kills: Number(s.kills), losses: Number(s.losses), isk_destroyed: Number(s.iskDestroyed || 0), isk_lost: Number(s.iskLost || 0), 
                        efficiency: Number(s.efficiency), ratio: Number(s.losses) > 0 ? Number(s.kills) / Number(s.losses) : Number(s.kills), activePilots: Number(s.activePilots), 
                        topShip: s.topShip, lastSeen: Number(s.lastSeen) 
                    };
                }
            });
            if (idsList.length === 1) allianceSummary = allianceStatsDict[idsList[0]];
        }

        // Process Corp Stats
        offset += idsList.length;
        if (corpIdsList.length > 0) {
            corpIdsList.forEach((id, i) => {
                const s = res[offset + i][1];
                if (s && Object.keys(s).length > 0) {
                    corpStatsDict[id] = { kills: Number(s.kills), losses: Number(s.losses), isk_destroyed: Number(s.iskDestroyed || 0), isk_lost: Number(s.iskLost || 0), efficiency: Number(s.efficiency), ratio: Number(s.losses) > 0 ? Number(s.kills) / Number(s.losses) : Number(s.kills), activePilots: Number(s.activePilots), topShip: s.topShip, lastSeen: Number(s.lastSeen) };
                }
            });
        }

        // Process Matrix
        let interactionMatrix = null;
        let vsHeadToHead = null;
        offset += corpIdsList.length;

        if (matrixPairs.length > 0) {
            interactionMatrix = {};
            matrixPairs.forEach((p, i) => {
                if(!interactionMatrix[p.k]) interactionMatrix[p.k] = {};
                interactionMatrix[p.k][p.v] = res[offset + i][1] || 0;
            });

            if (idsList.length === 2) {
                const a = idsList[0], b = idsList[1];
                vsHeadToHead = {
                    alliance_a: a, alliance_b: b,
                    a_killed_b: interactionMatrix[a]?.[b] || 0,
                    b_killed_a: interactionMatrix[b]?.[a] || 0
                };
            }
        }

        return [{ json: { 
            total_count: statsData.total_count, 
            stats_24h: statsData.stats_24h, 
            trends: trendsData, 
            isk_distribution, 
            activity_heatmap: statsData.activity_heatmap, 
            daily_stats: statsData.daily_stats, 
            top_systems: statsData.top_systems, 
            alliance_stats: allianceStatsDict, 
            alliance_summary: allianceSummary, 
            corporation_stats: corpStatsDict,
            latest_db_killmail_time: statsData.latest_db_killmail_time, 
            vs_head_to_head: vsHeadToHead, 
            interaction_matrix: interactionMatrix 
        } }];

    } catch (e) { 
        return [{ json: { error: e.message } }]; 
    } finally { 
        if (redis) redis.quit(); 
    }
})();
